import './style.css';
import catalog from '../content/properties.json';
import {createIcons,Search,X,Menu as MenuIcon,SlidersHorizontal,MapPin,Tag,Home as HomeIcon,BedDouble,Bath,Ruler,Banknote} from 'lucide';

const A=`${import.meta.env.BASE_URL}assets/`;
const basePath=new URL(import.meta.env.BASE_URL,location.origin).pathname.replace(/\/+$/,'');
const route=(path)=>{let clean=String(path||'').replace(/^\/+/, '');const baseName=basePath.replace(/^\/+/,'');if(baseName&&clean.startsWith(`${baseName}/`))clean=clean.slice(baseName.length+1);return `${basePath||''}/${clean}`.replace(/\/+/g,'/')};
const asset=(src)=>src?.startsWith('http')?src:`${import.meta.env.BASE_URL}${(src||'/assets/property-1.jpeg').replace(/^\/+/,'')}`;
let properties=catalog.properties.map((p,i)=>{const lines=p.text.split('\n').map(x=>x.trim()).filter(Boolean);const title=lines[5]||decodeURIComponent(new URL(p.url).pathname.split('/').pop()).replaceAll('-',' ');const price=lines.find(x=>/R?\$?\s?\d+.*MIL/i.test(x))||'Consulte';const area=(lines.find(x=>/\d+\s?m²/.test(x))||'').match(/\d+\s?m²/)?.[0]||'';return {id:i,url:new URL(p.url).pathname,title,price,size:area,status:'Ativo',updatedAt:'',city:'',address:'',year:'',description:'',image:asset(p.images[0]?.localSrc),images:p.images,raw:p.text,lines}});
const propertyPurpose=p=>/locação|locacao/i.test(p.raw)?'Locação':'Venda';
const propertyIsRecent_=p=>{const raw=String(p.updatedAt||'').trim();if(!raw)return window.__publicSynced&&properties.indexOf(p)===0;const match=raw.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/);const date=match?new Date(Number(match[3]),Number(match[2])-1,Number(match[1])):new Date(raw);return !Number.isNaN(date.getTime())&&(Date.now()-date.getTime())<14*24*60*60*1000};
const propertyTag_=p=>p.status==='Vendido'?'Vendido':p.status==='Alugado'?'Alugado':propertyPurpose(p);
const propertyBadges_=p=>{const badges=[];if(p.status==='Vendido')badges.push('<span class="status-badge is-sold">Vendido</span>');else if(p.status==='Alugado')badges.push('<span class="status-badge is-rented">Alugado</span>');if(!badges.length)badges.push(`<span class="status-badge">${propertyPurpose(p)}</span>`);return badges.join('')};
const propertyCity=p=>{const explicit=String(p.city||p['Cidade']||'').trim();if(explicit)return explicit;const text=`${p.title} ${p.raw}`.toLocaleLowerCase('pt-BR');if(/santos[\/–-]guarujá|guarujá[\/–-]santos/.test(text))return'Guarujá';if(/\b(santos|santista)\b/.test(text)&&/boqueirão|gonzaga|ponta da praia|embaré|aparecida|josé menino|marapé|campo grande|vila belmiro/.test(text))return'Santos';if(/guarujá|guaruja|pitangueiras|astúrias|asturias|enseada|tombo|jardim dos pássaros|jardim dos passaros|pernambuco|guaiúba|guaiuba/.test(text))return'Guarujá';return'Cidade não informada'};
const SHEET_URL='';
const AUTH_API_URL='https://script.google.com/macros/s/AKfycbxAUoa3za8ncWJIrhXnJ8rDJZgR6FC5wxqiV94MujHNWOFepWCge_7YuQMCTliXe8gdpQ/exec';
const ADMIN_API_URL='https://script.google.com/macros/s/AKfycbyNAD6mRDSAxwZbsY6n_keGo-3e9kgk2pEUCCpYXvyL6NvVFfB8tBEKggieyf4HHzoIAg/exec';
const adminReturnUrl_=()=>`${location.origin}${basePath}/?admin=1`;
const adminToken_=new URLSearchParams(location.search).get('adminToken')||sessionStorage.getItem('adminToken')||'';
if(adminToken_)sessionStorage.setItem('adminToken',adminToken_);
// Apps Script não expõe cabeçalhos CORS para chamadas autenticadas do GitHub Pages.
// GET usa JSONP e POST usa uma requisição simples (sem preflight), mantendo a sessão Google.
const nativeFetch=window.fetch.bind(window);
const apiJsonp=(url)=>new Promise((resolve,reject)=>{const callback=`__adminCallback${Date.now()}${Math.random().toString(36).slice(2)}`;const script=document.createElement('script');let timer;const cleanup=()=>{clearTimeout(timer);delete window[callback];script.remove()};window[callback]=data=>{cleanup();resolve({ok:true,status:200,json:async()=>data})};script.onerror=()=>{cleanup();reject(new Error('Não foi possível acessar o Apps Script.'))};timer=setTimeout(()=>{cleanup();reject(new Error('O Apps Script demorou para responder. Verifique a implantação da API.'))},12000);script.src=`${url}${url.includes('?')?'&':'?'}callback=${encodeURIComponent(callback)}&_=${Date.now()}`;document.head.append(script)});
window.fetch=(url,options={})=>{if(String(url).startsWith(ADMIN_API_URL)){const method=(options.method||'GET').toUpperCase();if(method==='GET')return apiJsonp(String(url));return nativeFetch(url,{...options,mode:'no-cors',credentials:'include'}).then(()=>({ok:true,status:200,json:async()=>({ok:true})}))}return nativeFetch(url,options)};
const fetchBeforeAdminToken_=window.fetch;window.fetch=(url,options={})=>{if(adminToken_&&String(url).startsWith(ADMIN_API_URL)){const securedUrl=new URL(String(url));securedUrl.searchParams.set('adminToken',adminToken_);return fetchBeforeAdminToken_(securedUrl.toString(),options)}return fetchBeforeAdminToken_(url,options)};
let activePageCleanups=[];const registerPageCleanup=fn=>activePageCleanups.push(fn);const disposePageEffects=()=>{activePageCleanups.splice(0).forEach(cleanup=>cleanup())};
function updatePublicListings_(){const render=(selector,items)=>{const grid=document.querySelector(selector);if(grid)grid.innerHTML=items.map(p=>Card({p})).join('')};render('.home-properties .property-grid',latestProperties_());render('.listing .property-grid',properties)}
function syncPublicProperties_(){if(location.pathname.includes('/admin')||new URLSearchParams(location.search).get('admin')==='1')return;fetch(`${ADMIN_API_URL}?action=public`).then(response=>response.json()).then(result=>{if(!result.ok||!result.properties?.length)return;const localByUrl=new Map(properties.map(property=>[property.url,property]));properties=result.properties.filter(property=>property.Status!=='Desativado'&&property['Status CMS']!=='Desativado').map((property,index)=>{const url=property.URL?new URL(property.URL).pathname:`/imoveis/${property.ID.toLowerCase()}`;const local=localByUrl.get(url)||properties[index]||{};const lines=[property['Título'],property['Preço (texto do site)'],property['Endereço / localização exibida'],'Espaço',property.Área,'Quartos',property.Quartos,'Banheiros',property.Banheiros,'Andares',property['Andares (campo do site)'],property['Características e resumo da descrição']].filter(Boolean);return {...local,id:property.ID,url,title:property['Título']||local.title,price:property['Preço (texto do site)']||local.price,size:property.Área||local.size,status:property.Status||property['Status CMS']||'Ativo',updatedAt:property['Atualizado em']||'',city:property.Cidade||'',address:property['Endereço / localização exibida']||'',year:property['Ano construção']||'',description:property['Características e resumo da descrição']||'',images:property.Images?.length?property.Images.map(photo=>({localSrc:photo.localSrc||photo.url,fallback:photo.fallback||photo.url})):local.images||[],image:property.Images?.[0]?.localSrc||local.image,raw:lines.join('\n'),lines}});const publicSignature=properties.map(property=>`${property.id}|${property.status}|${property.title}|${property.price}|${property.images?.map(image=>image.localSrc).join(',')||''}`).join('||');if(publicSignature===window.__publicSignature)return;window.__publicSignature=publicSignature;window.__publicSynced=true;if(window.__backgroundSync)updatePublicListings_();else{App();cleanGalleryControls();addGalleryArrows();initTrackGalleries();initAdvancedFilters();initTitleAnimations();initFooterDeveloper();initFooterParallax();initFaqAccordions();initContactSplit();initHeroLiquid()}}).catch(()=>{})}
const faqs=[
 ['Quais custos adicionais devo considerar ao comprar um imóvel no Guarujá, além do preço de venda?','Resposta: Além do valor do imóvel, você deve incluir despesas como Imposto de Transmissão de Bens Imóveis (ITBI), registro no Cartório de Imóveis, escritura pública (se não for financiado pelo SFH), e custos de corretagem. Se for um apartamento, verifique também o valor do condomínio e do IPTU.'],
 ['Quais são as principais exigências de garantia para um contrato de locação anual no Guarujá','As garantias mais comuns são caução, fiador ou seguro-fiança. A melhor opção depende do perfil do imóvel e do inquilino.'],
 ['É comum encontrar imóveis mobiliados para locação anual no Guarujá? O que devo verificar nesse caso?','Sim. Confira o inventário dos móveis, o estado de conservação, os valores de condomínio e IPTU e todos os itens descritos no contrato.']
];

function Header(){return `<header class="header"><a class="brand" href="${route('/')}">Aline Martins</a><button class="menu" aria-label="Abrir menu">☰</button><nav><a href="${route('/imoveis')}">Imóveis</a><a href="${route('/sobre')}">Sobre</a><a href="${route('/contato')}">Contato</a><a class="whatsapp" href="https://wa.me/13991909588">WhatsApp</a></nav></header>`}
function Footer(){return `<footer><a class="footer-brand" href="${route('/')}">Aline Martins</a><div class="footer-grid"><div><span>Corretora de Imóveis CRECI 285625-F</span></div><div><strong>Páginas</strong><a href="/">Home</a><a href="/imoveis">Imóveis</a><a href="/sobre">Sobre</a><a href="/contato">Contato</a></div><div><strong>Rede Sociais</strong><a href="https://www.instagram.com/alinemartins.imoveis/" target="_blank" rel="noreferrer">Instagram</a><a href="https://wa.me/13991909588" target="_blank" rel="noreferrer">WhatsApp</a></div></div><div class="footer-bottom"><span>Copyright © Todos os direitos reservados</span><a href="${route('/privacidade')}">Política de Privacidade</a><span>Desenvolvido por <b>haus.art.br</b></span></div></footer>`}
function FAQ(){return `<section class="faq"><div class="eyebrow">FAQ</div><h2>Suas perguntas respondidas</h2><p>Aqui estão as perguntas mais frequentes feitas pelos clientes.</p><div class="faq-list">${faqs.map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${q}<span>+</span></summary><div>${a}</div></details>`).join('')}</div></section>`}
function Card({p}){return `<a class="card" href="${route(p.url)}"><div class="card-image"><img src="${p.image}" data-fallback="${p.fallback||''}" alt="${p.title}"/>${propertyBadges_(p)}</div><div class="card-body"><h3>${p.title}</h3><strong>${p.price}</strong><div class="meta"><span>⌂ ${p.size||'Imóvel'}</span><span>♧ ${propertyCity(p)}</span></div></div></a>`}
function PropertyGrid({items=properties.slice(0,3)}={}){return `<div class="property-grid">${items.map(p=>Card({p})).join('')}</div>`}
function latestProperties_(){if(window.__publicSynced)return properties.slice(0,3);const dated=properties.some(property=>property['Atualizado em']);if(dated)return [...properties].sort((a,b)=>new Date(b['Atualizado em']||0)-new Date(a['Atualizado em']||0)).slice(0,3);return properties.slice(-3).reverse()}
function relatedProperties_(current){const index=properties.findIndex(property=>property.id===current.id||property.url===current.url);if(index<0)return properties.slice(0,3);return Array.from({length:Math.min(3,Math.max(properties.length-1,0))},(_,offset)=>properties[(index+offset+1)%properties.length]).filter(property=>property.id!==current.id)}
function Home(){return `<main><section class="hero" style="--hero-image:url('${A}hero.webp')">${Header()}<div class="hero-copy"><h1>Descubra o lugar<br/>perfeito para<br/>chamar de lar</h1></div></section><section class="gold-intro home-properties"><div class="gold-top"><h2>Encontre casas que combinam<br/>perfeitamente com seu estilo<br/>de vida</h2><a class="dark-button" href="/imoveis">Ver todos <span>→</span></a></div>${PropertyGrid({items:latestProperties_()})}</section>${FAQ()}</main>`}
function Imoveis(){return `<main><section class="page-top">${Header()}<div class="page-title"><h1>Descubra casas feitas sob medida<br/>para o seu estilo de vida único.</h1><p>Entre num portfólio selecionado de residências deslumbrantes.</p></div></section><section class="listing"><div class="filters"><select class="property-filter"><option value="all">Todos os imóveis</option><option value="apartamento">Apartamentos</option><option value="casa">Casas</option></select><button class="filter-submit">Buscar imóvel <span>⌕</span></button></div><div class="eyebrow">Venda</div>${PropertyGrid({items:properties})}</section>${FAQ()}</main>`}
function Detail({p}){const body=p.lines.slice(6).filter(x=>!['Detalhes','Espaço','Venda','Locação'].includes(x)&&x!==p.price&&!/^Rua |^Av |^Praia |^Avenida/i.test(x));const photos=[...new Map(p.images.filter(x=>x.localSrc&&!x.localSrc.endsWith('.svg')).map(x=>({...x,src:asset(x.localSrc)})).map(photo=>[photo.src,photo])).values()];const keys=['Espaço','Ano construção','Andares','Quartos','Banheiros'];const detailValue=(key,fallback='')=>{const i=p.lines.lastIndexOf(key);const v=p.lines[i+1];return !v||keys.includes(v)?fallback:v};const area=detailValue('Espaço',p.size||'');const rooms=detailValue('Quartos','');const baths=detailValue('Banheiros','');const floors=detailValue('Andares','');const address=p.lines.find(x=>/^Rua|^Av |^Praia|^Avenida/i.test(x))||'Guarujá, SP';const whatsappText=`Olá, gostaria de solicitar uma visita para o imóvel:\n\n${p.title}\nPreço: ${p.price}\nÁrea: ${area}\nQuartos: ${rooms}\nBanheiros: ${baths}\nLocalização: ${address}`;const whatsappUrl=`https://wa.me/13991909588?text=${encodeURIComponent(whatsappText)}`;return `<main class="detail-page"><section class="detail-shell">${Header()}<div class="detail-title"><h1>${p.title}</h1></div><img class="detail-hero-image" src="${photos[0]?.src||p.image}" alt="${p.title}"/><div class="detail-info"><article class="detail-description"><span class="pill">${propertyPurpose(p)}</span><div class="address">⌖ ${address}</div>${body.slice(0,10).map(x=>`<p>${x}</p>`).join('')}<h2>${p.price}</h2></article><aside class="facts"><h2>Detalhes</h2><div><span>Espaço</span><b>${area}</b></div><div><span>Ano construção</span><b>${detailValue('Ano construção','')}</b></div><div><span>Andares</span><b>${floors}</b></div><div><span>Quartos</span><b>${rooms}</b></div><div><span>Banheiros</span><b>${baths}</b></div><a class="dark-button" href="${whatsappUrl}" target="_blank" rel="noreferrer">Solicitar visita <span>→</span></a></aside></div><div class="map-row"><div class="gallery-column"><div class="gallery-main"><img class="gallery-current" src="${photos[0]?.src||p.image}" alt="${p.title} — galeria"/><div class="gallery-dots">${photos.map((photo,i)=>`<button type="button" class="gallery-dot ${i===0?'active':''}" data-gallery-src="${photo.src}" aria-label="Mostrar imagem ${i+1}"></button>`).join('')}</div></div><div class="gallery-thumbs">${photos.map((photo,i)=>`<button type="button" class="gallery-thumb ${i===0?'active':''}" data-gallery-src="${photo.src}" aria-label="Mostrar imagem ${i+1}"><img src="${photo.src}" alt="${p.title} — imagem ${i+1}" loading="lazy"/></button>`).join('')}</div></div><div class="location"><h2>Localização</h2><iframe title="Mapa da localização" src="https://maps.google.com/maps?q=${encodeURIComponent(address)}&z=15&output=embed" loading="lazy"></iframe></div></div><section class="related"><div class="eyebrow">Outros imóveis</div><h2>Encontre casas que combinam perfeitamente<br/>com seu estilo de vida</h2><a class="dark-button" href="/imoveis">Ver todos <span>→</span></a>${PropertyGrid({items:relatedProperties_(p)})}</section>${FAQ()}</section></main>`}
function formatPriceDisplay_(value){const raw=String(value||'').trim();if(!raw)return'Consulte';if(/^R\$/.test(raw))return raw;const normalized=raw.includes(',')?raw.replace(/\./g,'').replace(',','.'):raw.replace(/[^0-9.-]/g,'');const number=Number(normalized);return Number.isNaN(number)?raw:number.toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}
function formatFloorDisplay_(value){const match=String(value||'').match(/\d+/);return match?`${Number(match[0])}º andar`:'Consultar'}
function DetailImproved({p}){const photos=[...new Map((p.images||[]).filter(x=>x.localSrc||x.url).map(x=>({...x,src:asset(x.localSrc||x.url)})).map(photo=>[photo.src,photo])).values()];const address=p.address||p.lines?.find(x=>/^Rua |^Av |^Praia |^Avenida/i.test(x))||'Localização não informada';const area=p.size||'Consultar';const rooms=p.lines?.[p.lines.lastIndexOf('Quartos')+1]||'Consultar';const baths=p.lines?.[p.lines.lastIndexOf('Banheiros')+1]||'Consultar';const floors=formatFloorDisplay_(p.lines?.[p.lines.lastIndexOf('Andares')+1]);const year=p.year||'Consultar';const description=(p.description||'').split(/\n+/).map(text=>text.trim()).filter(Boolean);const price=formatPriceDisplay_(p.price);const whatsappText=`Olá, gostaria de solicitar uma visita para o imóvel:\n\n${p.title}\nPreço: ${price}\nMetragem: ${area}\nQuartos: ${rooms}\nBanheiros: ${baths}\nLocalização: ${address}`;const whatsappUrl=`https://wa.me/13991909588?text=${encodeURIComponent(whatsappText)}`;return `<main class="detail-page"><section class="detail-shell">${Header()}<div class="detail-title"><h1>${p.title}</h1></div><img class="detail-hero-image" src="${photos[0]?.src||p.image}" alt="${p.title}"/><div class="detail-info"><article class="detail-description"><span class="pill">${propertyTag_(p)}</span><div class="address">⌖ ${address}</div>${description.map(text=>`<p>${text}</p>`).join('')}<h2>${price}</h2></article><aside class="facts"><h2>Detalhes</h2><div><span>Metragem</span><b>${area}</b></div><div><span>Ano construção</span><b>${year||'Consultar'}</b></div><div><span>Andar</span><b>${floors}</b></div><div><span>Quartos</span><b>${rooms}</b></div><div><span>Banheiros</span><b>${baths}</b></div><a class="dark-button" href="${whatsappUrl}" target="_blank" rel="noreferrer">Solicitar visita <span>→</span></a></aside></div><div class="map-row"><div class="gallery-column"><div class="gallery-main"><img class="gallery-current" src="${photos[0]?.src||p.image}" alt="${p.title} — galeria"/><div class="gallery-dots">${photos.map((photo,i)=>`<button type="button" class="gallery-dot ${i===0?'active':''}" data-gallery-src="${photo.src}" aria-label="Mostrar imagem ${i+1}"></button>`).join('')}</div></div><div class="gallery-thumbs">${photos.map((photo,i)=>`<button type="button" class="gallery-thumb ${i===0?'active':''}" data-gallery-src="${photo.src}" aria-label="Mostrar imagem ${i+1}"><img src="${photo.src}" alt="${p.title} — imagem ${i+1}" loading="lazy"/></button>`).join('')}</div></div><div class="location"><h2>Localização</h2><iframe title="Mapa da localização" src="https://maps.google.com/maps?q=${encodeURIComponent(address)}&z=15&output=embed" loading="lazy"></iframe></div></div><section class="related"><div class="eyebrow">Outros imóveis</div><h2>Encontre casas que combinam perfeitamente<br/>com seu estilo de vida</h2><a class="dark-button" href="/imoveis">Ver todos <span>→</span></a>${PropertyGrid({items:relatedProperties_(p)})}</section>${FAQ()}</section></main>`}
Detail=DetailImproved;function Sobre(){return `<main><section class="about-hero" style="--about-image:url('${A}about.webp')">${Header()}<div><div class="eyebrow">Sobre</div><h1>Aline Martins</h1><p>🏠 Corretora de Imóveis – CRECI 285625-F. e Perita avaliadora de Imóveis - Em Santos e região, ajudando você a viver bem no imóvel certo.</p><div class="checks">✅ Avaliação Imobiliária<br/>✅ Compra<br/>✅ Venda<br/>✅ Locação</div><a class="dark-button" href="/contato">Entrar em contato <span>→</span></a></div></section><section class="about-content"><div class="about-photo"><img src="${A}about.webp" alt="Aline Martins"/></div><div><div class="eyebrow">Experiência</div><h2>Por que escolher a Aline Martins?</h2><p>Cuidamos de cada detalhe com atenção e experiência, do primeiro contato à entrega das chaves (e além).</p><div class="steps">${[['Consultoria Inicial','Ajudamos você a encontrar o imóvel ideal — ou a anunciar o seu — com estratégias personalizadas de marketing e divulgação.'],['Busca ou Divulgação do Imóvel','Ajudamos você a encontrar o imóvel ideal — ou a anunciar o seu — com estratégias personalizadas de marketing e divulgação.'],['Análise de Mercado e Estratégia','Realizamos uma análise completa do mercado imobiliário local para orientar suas decisões com base em dados reais, tendências e oportunidades da região.'],['Preparação e Valorização do Imóvel','Conduzimos toda a negociação com transparência e segurança, garantindo o melhor acordo e cuidando de toda a documentação até a assinatura final.'],['Negociação e Fechamento','Conduzimos toda a negociação com transparência e segurança, garantindo o melhor acordo e cuidando de toda a documentação até a assinatura final.'],['Suporte Pós-venda','Nosso compromisso continua depois da entrega das chaves. Estamos sempre à disposição para acompanhar seus próximos passos com confiança e tranquilidade.']].map(([h,p])=>`<article><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></div></section>${FAQ()}</main>`}
function Contato(){return `<main><section class="contact-top">${Header()}<div class="contact-wrap"><h1>Fale comigo</h1><p>Precisa de ajuda? Consulte nossas Perguntas Frequentes para obter respostas rápidas ou entre em contato conosco diretamente.</p><form><label>Objetivo<select name="objetivo"><option>Comprar</option><option>Vender</option><option>Consultar</option></select></label><div class="two"><label>Nome<input name="nome" placeholder="Seu nome aqui" required/></label><label>Telefone<input name="telefone" placeholder="(DDD) 0000-0000" pattern="[0-9 ()+-]{8,}" required/></label></div><label>Email address<input name="email" type="email" placeholder="contato@email.com.br" required/></label><label>Mensagem<textarea name="mensagem" placeholder="Sua mensagem aqui" minlength="10" required></textarea></label><label class="hp-field" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"/></label><button class="submit" type="submit">Revisar mensagem</button><div class="contact-review" hidden><strong>Revise seus dados antes de enviar</strong><div class="review-summary"></div><div class="review-actions"><button type="button" class="review-edit">Editar</button><button type="button" class="review-confirm">Confirmar envio</button></div></div><div class="success" hidden>Mensagem enviada. Entraremos em contato em breve.</div></form></div></section>${FAQ()}</main>`}
function Admin(){return `<main class="admin-page"><section class="admin-access">${Header()}<div class="admin-shell"><div class="admin-intro"><div class="eyebrow">Área restrita</div><h1>Atualize seus imóveis com segurança.</h1><p>Entre no painel exclusivo para revisar preços, descrições, fotos e disponibilidade dos anúncios.</p><div class="sheet-status"><span class="status-dot"></span><div><strong>Fonte de dados conectável</strong><small>Google Sheets · Inventário de imóveis</small></div></div><a class="sheet-link" href="${SHEET_URL}" target="_blank" rel="noreferrer">Abrir planilha de inventário <span>↗</span></a></div><form class="admin-form"><div class="admin-form-heading"><span class="admin-lock">⌁</span><div><h2>Acesso administrativo</h2><p>Use suas credenciais autorizadas.</p></div></div><label class="admin-remember"><input type="checkbox" name="remember"/> <span>Manter sessão neste dispositivo</span></label><button class="admin-submit" type="submit">Entrar no painel <span>→</span></button><p class="admin-message" role="status" hidden></p><small class="admin-security">A autenticação será conectada ao provedor seguro antes da publicação.</small></form></div></section></main>`}
function Privacidade(){return `<main><section class="page-top policy-top">${Header()}<div class="page-title"><div class="eyebrow">Legal</div><h1>Política de Privacidade</h1><p>Como cuidamos dos seus dados e da sua privacidade.</p></div></section><article class="policy-content"><p>Esta Política de Privacidade explica como Aline Martins Corretora de Imóveis trata as informações fornecidas por visitantes e clientes deste site, em conformidade com a Lei Geral de Proteção de Dados Pessoais (Lei nº 13.709/2018).</p><h2>1. Dados coletados</h2><p>Podemos receber dados informados voluntariamente nos formulários de contato, como nome, telefone, e-mail, objetivo do atendimento e mensagem. Também podemos coletar informações técnicas básicas, como endereço IP, navegador e páginas acessadas, para segurança e melhoria do site.</p><h2>2. Como usamos os dados</h2><p>Os dados são utilizados para responder solicitações, apresentar imóveis, agendar visitas, prestar atendimento imobiliário, melhorar a experiência de navegação e cumprir obrigações legais.</p><h2>3. Compartilhamento</h2><p>Não vendemos seus dados pessoais. O compartilhamento ocorre apenas quando necessário para prestar o serviço solicitado, cumprir obrigação legal ou proteger direitos, sempre respeitando a legislação aplicável.</p><h2>4. Cookies e serviços externos</h2><p>O site pode utilizar recursos de terceiros, como mapas e links para redes sociais. Esses serviços podem aplicar suas próprias políticas de privacidade. Você pode controlar cookies pelas configurações do seu navegador.</p><h2>5. Segurança e retenção</h2><p>Adotamos medidas razoáveis para proteger as informações contra acesso indevido. Mantemos os dados somente pelo período necessário para cumprir as finalidades informadas ou obrigações legais.</p><h2>6. Seus direitos</h2><p>Você pode solicitar confirmação do tratamento, acesso, correção, atualização ou eliminação dos seus dados, além de outras garantias previstas na LGPD. Para exercer seus direitos, entre em contato pela página <a href="${route('/contato')}">Contato</a>.</p><h2>7. Atualizações</h2><p>Esta política pode ser atualizada para refletir mudanças legais ou operacionais. Recomendamos consultar esta página periodicamente.</p><p class="policy-updated">Última atualização: outubro de 2026.</p></article></main>`}
function initGalleries(){document.querySelectorAll('.gallery-column').forEach(gallery=>{const image=gallery.querySelector('.gallery-current');const controls=[...gallery.querySelectorAll('[data-gallery-src]')];const sources=[...new Set(controls.map(control=>control.dataset.gallerySrc))];if(!image||sources.length<2)return;let index=0;const show=next=>{index=(next+sources.length)%sources.length;image.classList.remove('is-sliding');void image.offsetWidth;image.classList.add('is-sliding');image.src=sources[index];controls.forEach(control=>control.classList.toggle('active',control.dataset.gallerySrc===sources[index]))};gallery.querySelector('.gallery-arrow.prev')?.addEventListener('click',()=>show(index-1));gallery.querySelector('.gallery-arrow.next')?.addEventListener('click',()=>show(index+1));let timer=setInterval(()=>show(index+1),4200);gallery.addEventListener('mouseenter',()=>clearInterval(timer));gallery.addEventListener('mouseleave',()=>{clearInterval(timer);timer=setInterval(()=>show(index+1),4200)})})}
function initPushGalleries(){document.querySelectorAll('.gallery-column').forEach(gallery=>{if(gallery.dataset.pushReady)return;const frame=gallery.querySelector('.gallery-main');const image=gallery.querySelector('.gallery-current');const controls=[...gallery.querySelectorAll('[data-gallery-src]')];const sources=[...new Set(controls.map(control=>control.dataset.gallerySrc))];if(!frame||!image||sources.length<2)return;gallery.dataset.pushReady='true';let index=0;const showSource=src=>{const nextIndex=sources.indexOf(src);if(nextIndex<0||nextIndex===index)return;const next=image.cloneNode(true);next.className='gallery-current gallery-next';next.src=src;frame.appendChild(next);image.classList.add('gallery-out');next.classList.add('gallery-in');index=nextIndex;controls.forEach(control=>control.classList.toggle('active',control.dataset.gallerySrc===src));window.setTimeout(()=>{image.src=src;image.className='gallery-current';next.remove()},620)};const show=next=>(showSource(sources[(next+sources.length)%sources.length]));gallery.addEventListener('click',event=>{const control=event.target.closest('[data-gallery-src]');if(!control)return;event.preventDefault();event.stopPropagation();showSource(control.dataset.gallerySrc)},true);let timer=setInterval(()=>show(index+1),2800);gallery.addEventListener('mouseenter',()=>clearInterval(timer));gallery.addEventListener('mouseleave',()=>{clearInterval(timer);timer=setInterval(()=>show(index+1),2800)})})}
function initTrackGalleries(){document.querySelectorAll('.gallery-column').forEach(gallery=>{if(gallery.dataset.trackReady)return;const frame=gallery.querySelector('.gallery-main');const current=frame?.querySelector('.gallery-current');const controls=[...gallery.querySelectorAll('[data-gallery-src]')];const sources=[...new Set(controls.map(control=>control.dataset.gallerySrc))];if(!frame||!current||sources.length<2)return;gallery.dataset.trackReady='true';const track=document.createElement('div');track.className='gallery-track';sources.forEach((src,index)=>{const image=document.createElement('img');image.src=src;image.alt=current.alt;image.loading=index?'lazy':'eager';track.append(image)});current.remove();frame.prepend(track);let index=0;const show=next=>{index=(next+sources.length)%sources.length;track.style.transform=`translateX(-${index*100}%)`;controls.forEach(control=>control.classList.toggle('active',control.dataset.gallerySrc===sources[index]))};gallery.addEventListener('click',event=>{const control=event.target.closest('[data-gallery-src]');if(!control)return;event.preventDefault();event.stopPropagation();show(sources.indexOf(control.dataset.gallerySrc))},true);let timer=setInterval(()=>show(index+1),2800);gallery.addEventListener('mouseenter',()=>clearInterval(timer));gallery.addEventListener('mouseleave',()=>{clearInterval(timer);timer=setInterval(()=>show(index+1),2800)});registerPageCleanup(()=>clearInterval(timer))})}
function cleanGalleryControls(){document.querySelectorAll('.gallery-column').forEach(gallery=>['gallery-dot','gallery-thumb'].forEach(kind=>{const seen=new Set();gallery.querySelectorAll(`.${kind}`).forEach(control=>{const src=control.dataset.gallerySrc;if(seen.has(src))control.remove();else seen.add(src)})}))}
function addGalleryArrows(){document.querySelectorAll('.gallery-column').forEach(gallery=>{const frame=gallery.querySelector('.gallery-main');if(!frame||frame.querySelector('.gallery-arrow'))return;frame.insertAdjacentHTML('beforeend','<button class="gallery-arrow prev" type="button" aria-label="Imagem anterior">‹</button><button class="gallery-arrow next" type="button" aria-label="Próxima imagem">›</button>');frame.querySelectorAll('.gallery-arrow').forEach(arrow=>arrow.addEventListener('click',()=>{const dots=[...gallery.querySelectorAll('.gallery-dot')];const active=Math.max(0,dots.findIndex(dot=>dot.classList.contains('active')));dots[(active+(arrow.classList.contains('next')?1:-1)+dots.length)%dots.length]?.click()}))})}
function initGalleryZoom(){if(document.querySelector('.gallery-lightbox'))return;document.body.insertAdjacentHTML('beforeend','<div class="gallery-lightbox" hidden role="dialog" aria-modal="true" aria-label="Imagem ampliada"><button type="button" class="gallery-lightbox-close" aria-label="Fechar imagem ampliada">×</button><button type="button" class="gallery-lightbox-arrow prev" aria-label="Imagem anterior">‹</button><img alt=""><button type="button" class="gallery-lightbox-arrow next" aria-label="Próxima imagem">›</button></div>');const lightbox=document.querySelector('.gallery-lightbox');const enlarged=lightbox.querySelector('img');let gallery=null,sources=[],index=0;const close=()=>{lightbox.hidden=true;document.body.classList.remove('gallery-zoom-open')};const show=next=>{if(!sources.length)return;index=(next+sources.length)%sources.length;enlarged.src=sources[index];if(gallery){const track=gallery.querySelector('.gallery-track');if(track)track.style.transform='translateX(-'+(index*100)+'%)';gallery.querySelectorAll('[data-gallery-src]').forEach(control=>control.classList.toggle('active',control.dataset.gallerySrc===sources[index]))}};document.addEventListener('click',event=>{const image=event.target.closest('.gallery-track img');if(!image)return;gallery=image.closest('.gallery-column');sources=[...gallery.querySelectorAll('.gallery-track img')].map(item=>item.currentSrc||item.src);index=sources.indexOf(image.currentSrc||image.src);enlarged.alt=image.alt;show(index);lightbox.hidden=false;document.body.classList.add('gallery-zoom-open')});lightbox.addEventListener('click',event=>{if(event.target===lightbox||event.target.closest('.gallery-lightbox-close'))close();else if(event.target.closest('.gallery-lightbox-arrow.next'))show(index+1);else if(event.target.closest('.gallery-lightbox-arrow.prev'))show(index-1)});document.addEventListener('keydown',event=>{if(lightbox.hidden)return;if(event.key==='Escape')close();if(event.key==='ArrowRight')show(index+1);if(event.key==='ArrowLeft')show(index-1)})}
function initFooterDeveloper(){document.querySelectorAll('.footer-bottom>span:last-child').forEach(item=>{if(item.dataset.linkReady)return;item.dataset.linkReady='true';item.innerHTML='Desenvolvido por <a class="developer-link" href="https://haus.art.br" target="_blank" rel="noreferrer">haus.art.br</a>'})}
function initFooterParallax(){const footer=document.querySelector('footer');const brand=footer?.querySelector('.footer-brand');if(!footer||!brand||footer.dataset.parallaxReady)return;footer.dataset.parallaxReady='true';footer.classList.add('footer-parallax-ready');if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){brand.style.opacity='1';brand.style.transform='none';return}let ticking=false;const update=()=>{ticking=false;const rect=footer.getBoundingClientRect();const progress=Math.max(0,Math.min(1,(window.innerHeight-rect.top)/(window.innerHeight*.55)));brand.style.opacity='1';brand.style.transform='translate3d(0,'+((1-progress)*-110)+'px,0)'};const onScroll=()=>{if(!ticking){ticking=true;requestAnimationFrame(update)}};window.addEventListener('scroll',onScroll,{passive:true});registerPageCleanup(()=>window.removeEventListener('scroll',onScroll));update()}
function initWhatsAppWidget(){if(document.querySelector('.whatsapp-widget'))return;document.body.insertAdjacentHTML('beforeend','<aside class="whatsapp-widget"><button class="whatsapp-float" type="button" aria-label="Abrir atendimento pelo WhatsApp"><span>◔</span><b>WhatsApp</b></button><div class="whatsapp-box" hidden><strong>Como podemos ajudar?</strong><p>Envie sua pergunta e fale diretamente com a corretora.</p><textarea placeholder="Digite sua pergunta..."></textarea><button class="whatsapp-send" type="button">Enviar no WhatsApp <span>→</span></button></div></aside>');const widget=document.querySelector('.whatsapp-widget');widget.querySelector('.whatsapp-float span').innerHTML='<img src="'+asset('/assets/whatsapp.svg')+'" alt="" aria-hidden="true">';const toggle=widget.querySelector('.whatsapp-float');const box=widget.querySelector('.whatsapp-box');toggle.addEventListener('click',()=>{box.hidden=!box.hidden;if(!box.hidden)widget.querySelector('textarea').focus()});widget.querySelector('.whatsapp-send').addEventListener('click',()=>{const message=widget.querySelector('textarea').value.trim()||'Olá, gostaria de saber mais sobre os imóveis disponíveis.';window.open(`https://wa.me/13991909588?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer')})}
function initContactSplit(){const section=document.querySelector('.contact-top');const form=section?.querySelector('form');if(!section||!form)return;const update=()=>{const sectionRect=section.getBoundingClientRect();const formRect=form.getBoundingClientRect();section.style.setProperty('--contact-split',`${formRect.top-sectionRect.top+formRect.height/2}px`)};update();if(section.dataset.splitBound)return;section.dataset.splitBound='true';window.addEventListener('resize',update);registerPageCleanup(()=>window.removeEventListener('resize',update))}
function initTitleAnimations(){document.querySelectorAll('main h1,main h2').forEach(title=>{if(title.dataset.wordsAnimated)return;title.dataset.wordsAnimated='true';const walker=document.createTreeWalker(title,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);let index=0;nodes.forEach(node=>{const fragment=document.createDocumentFragment();node.textContent.split(/(\s+)/).forEach(part=>{if(/^\s+$/.test(part)||!part){fragment.append(part);return}const word=document.createElement('span');word.className='title-word';word.style.setProperty('--word-index',index++);word.textContent=part;fragment.append(word)});node.replaceWith(fragment)})})}
function initFaqAccordions(){document.querySelectorAll('.faq summary').forEach(summary=>{if(summary.dataset.independent)return;summary.dataset.independent='true';summary.addEventListener('click',event=>{event.preventDefault();const details=summary.parentElement;if(details.open){details.open=false}else{details.parentElement.querySelectorAll('details[open]').forEach(other=>{if(other!==details)other.open=false});details.open=true}})})}
function initAdvancedFilters(){const filters=document.querySelector('.filters');if(!filters||filters.dataset.advancedReady)return;filters.dataset.advancedReady='true';filters.innerHTML='<label class="search-field"><input class="property-search" type="search" placeholder="Buscar imóvel" autocomplete="off"/><span aria-hidden="true">⌕</span><button class="filter-clear" type="button" aria-label="Limpar filtros">×</button></label><select class="filter-city" aria-label="Cidade"><option value="all">Cidade</option><option value="guaruja">Guarujá</option><option value="santos">Santos</option><option value="outra">Outras cidades</option></select><select class="filter-purpose" aria-label="Finalidade"><option value="all">Finalidade</option><option value="venda">Venda</option><option value="locacao">Locação</option></select><select class="filter-type" aria-label="Tipo de imóvel"><option value="all">Tipo de imóvel</option><option value="apartamento">Apartamento</option><option value="casa">Casa</option></select><select class="filter-rooms" aria-label="Quartos"><option value="all">Quartos</option><option value="1">1 quarto</option><option value="2">2 quartos</option><option value="3">3 quartos</option><option value="4">4+ quartos</option></select><select class="filter-baths" aria-label="Banheiros"><option value="all">Banheiros</option><option value="1">1 banheiro</option><option value="2">2 banheiros</option><option value="3">3+ banheiros</option></select><select class="filter-area" aria-label="Área"><option value="all">Área</option><option value="50">Até 50m²</option><option value="80">51–80m²</option><option value="81">81m² ou mais</option></select><select class="filter-price" aria-label="Preço"><option value="all">Preço</option><option value="300">Até R$ 300 mil</option><option value="500">R$ 301–500 mil</option><option value="501">Acima de R$ 500 mil</option></select>';const getNumber=(p,key)=>{const i=p.lines.lastIndexOf(key);return Number.parseFloat((p.lines[i+1]||'').replace(/[^0-9,]/g,'').replace(',','.'))||0};const getPrice=p=>Number.parseFloat((p.price||'').replace(/[^0-9,]/g,'').replace(',','.'))||0;const cityOf=p=>propertyCity(p).toLocaleLowerCase('pt-BR').replace('á','a').replace(' ','');const update=()=>{const query=filters.querySelector('.property-search').value.trim().toLocaleLowerCase('pt-BR');const city=filters.querySelector('.filter-city').value;const purpose=filters.querySelector('.filter-purpose').value;const type=filters.querySelector('.filter-type').value;const rooms=filters.querySelector('.filter-rooms').value;const baths=filters.querySelector('.filter-baths').value;const area=filters.querySelector('.filter-area').value;const price=filters.querySelector('.filter-price').value;const items=properties.filter(p=>{const text=`${p.title} ${p.raw} ${p.price} ${p.size}`.toLocaleLowerCase('pt-BR');const r=getNumber(p,'Quartos');const b=getNumber(p,'Banheiros');const a=getNumber(p,'Espaço')||Number.parseFloat(p.size)||0;const v=getPrice(p);const pCity=cityOf(p);const pPurpose=/locação|locacao/.test(text)?'locacao':'venda';const pType=/casa|sobrado/.test(text)&&!/apartamento/.test(text)?'casa':'apartamento';return(!query||text.includes(query))&&(city==='all'||pCity===city)&&(purpose==='all'||pPurpose===purpose)&&(type==='all'||pType===type)&&(rooms==='all'||(rooms==='4'?r>=4:r===Number(rooms)))&&(baths==='all'||(baths==='3'?b>=3:b===Number(baths)))&&(area==='all'||(area==='50'?a<=50:area==='80'?a>50&&a<=80:a>=81))&&(price==='all'||(price==='300'?v<=300:price==='500'?v>300&&v<=500:v>500))});const grid=document.querySelector('.listing .property-grid');if(grid)grid.innerHTML=items.length?items.map(p=>Card({p})).join(''):'<p class="no-results">Nenhum imóvel encontrado.</p>'};let filterTimer;const schedule=()=>{clearTimeout(filterTimer);filterTimer=setTimeout(update,160)};filters.querySelectorAll('input,select').forEach(control=>control.addEventListener(control.tagName==='INPUT'?'input':'change',schedule));filters.querySelector('.filter-clear').addEventListener('click',()=>{filters.querySelectorAll('select').forEach(select=>select.value='all');filters.querySelector('.property-search').value='';update()});registerPageCleanup(()=>clearTimeout(filterTimer));update()}
function initFilterUI(){const filters=document.querySelector('.filters');if(!filters||filters.dataset.filterUiReady)return;filters.dataset.filterUiReady='true';const iconMap={'filter-city':'map-pin','filter-purpose':'tag','filter-type':'home','filter-rooms':'bed-double','filter-baths':'bath','filter-area':'ruler','filter-price':'banknote'};filters.querySelector('.search-field span').innerHTML='<i data-lucide="search"></i>';filters.querySelector('.filter-clear').innerHTML='<i data-lucide="x"></i>';const selects=[...filters.querySelectorAll('select')];selects.forEach(select=>{const wrapper=document.createElement('label');wrapper.className='filter-control';wrapper.innerHTML=`<i data-lucide="${iconMap[select.className.split(' ').find(name=>iconMap[name])]}"></i>`;select.replaceWith(wrapper);wrapper.append(select)});const advanced=selects.filter(control=>/filter-(type|rooms|baths|area|price)/.test(control.className)).map(control=>control.closest('.filter-control'));if(!advanced.length)return;const more=document.createElement('div');more.className='filters-more';more.hidden=true;advanced.forEach(control=>more.append(control));const toggle=document.createElement('button');toggle.type='button';toggle.className='filters-more-toggle';toggle.setAttribute('aria-expanded','false');toggle.innerHTML='<i data-lucide="sliders-horizontal"></i><span>Mais filtros</span>';toggle.addEventListener('click',()=>{more.hidden=!more.hidden;toggle.setAttribute('aria-expanded',String(!more.hidden));toggle.querySelector('span').textContent=more.hidden?'Mais filtros':'Menos filtros'});const clear=filters.querySelector('.filter-clear');filters.insertBefore(toggle,clear?.closest('.search-field')?.nextSibling||filters.firstChild);filters.append(more);createIcons({icons:{Search,X,SlidersHorizontal,MapPin,Tag,Home:HomeIcon,BedDouble,Bath,Ruler,Banknote}})}
function initSearchSuggestions(){const field=document.querySelector('.search-field');const input=field?.querySelector('.property-search');if(!field||!input||field.dataset.suggestionsReady)return;field.dataset.suggestionsReady='true';const list=document.createElement('div');list.className='search-suggestions';list.hidden=true;field.append(list);const render=()=>{const query=input.value.trim().toLocaleLowerCase('pt-BR');list.replaceChildren();if(query.length<2){list.hidden=true;return}const matches=properties.filter(p=>{const address=p.lines.find(x=>/^Rua|^Av |^Praia |^Avenida/i.test(x))||'';return`${p.title} ${propertyCity(p)} ${p.price} ${address}`.toLocaleLowerCase('pt-BR').includes(query)}).sort((a,b)=>a.title.toLocaleLowerCase('pt-BR').indexOf(query)-b.title.toLocaleLowerCase('pt-BR').indexOf(query)).slice(0,5);if(!matches.length){const empty=document.createElement('div');empty.className='search-empty';empty.textContent='Nenhum imóvel encontrado';list.append(empty)}else matches.forEach(p=>{const item=document.createElement('button');item.type='button';item.className='search-suggestion';const title=document.createElement('strong');title.textContent=p.title;const meta=document.createElement('span');meta.textContent=`${propertyCity(p)} · ${p.price}`;item.append(title,meta);item.addEventListener('click',()=>navigate(p.url));list.append(item)});list.hidden=false};input.addEventListener('input',render);field.querySelector('.filter-clear')?.addEventListener('click',()=>{list.hidden=true;list.replaceChildren()})}
function initHeaderMenu(){document.querySelectorAll('.header').forEach(header=>{if(header.dataset.menuReady)return;header.dataset.menuReady='true';const button=header.querySelector('.menu');const nav=header.querySelector('nav');if(!button||!nav)return;const setOpen=open=>{nav.classList.toggle('open',open);button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');button.innerHTML=`<i data-lucide="${open?'x':'menu'}"></i>`;createIcons({icons:{X,Menu:MenuIcon}})};setOpen(false);button.addEventListener('click',()=>setOpen(!nav.classList.contains('open')));nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>setOpen(false)))})}
function initAdminPage(){const form=document.querySelector('.admin-form');if(!form||form.dataset.ready)return;form.dataset.ready='true';const message=form.querySelector('.admin-message');form.querySelector('.admin-form-heading p').textContent='Acesso protegido pela sua conta Google.';form.querySelector('.admin-submit').innerHTML='Conectar com Google <span>→</span>';const showMessage=text=>{message.textContent=text;message.hidden=false;message.className='admin-message is-pending'};const render=properties=>{form.hidden=true;const panel=document.createElement('section');panel.className='admin-dashboard';panel.innerHTML='<div class="admin-dashboard-head"><div><div class="eyebrow">Painel conectado</div><h2>Imóveis cadastrados</h2><p>Edite os dados e salve as alterações na planilha.</p></div><a class="sheet-link" href="'+SHEET_URL+'" target="_blank" rel="noreferrer">Abrir Sheets ↗</a></div><div class="admin-property-list"></div>';const list=panel.querySelector('.admin-property-list');properties.forEach(property=>{const item=document.createElement('article');item.className='admin-property';const title=document.createElement('h3');title.textContent=property['Título'];const meta=document.createElement('p');meta.textContent=`${property.ID} · ${property['Preço (texto do site)']} · ${property['Endereço / localização exibida']}`;const edit=document.createElement('button');edit.type='button';edit.className='admin-edit';edit.textContent='Editar';const editor=document.createElement('form');editor.className='admin-editor';editor.hidden=true;editor.innerHTML='<label class="quick-title-field">Título<textarea name="title" rows="3" required></textarea></label><label>Preço<input name="price" required></label><label>Endereço<input name="address"></label><div class="admin-editor-actions"><button type="submit">Salvar alteração</button><button type="button" class="admin-cancel">Cancelar</button></div>';editor.title.value=property['Título'];editor.price.value=property['Preço (texto do site)'];editor.address.value=property['Endereço / localização exibida'];edit.addEventListener('click',()=>{editor.hidden=!editor.hidden});editor.querySelector('.admin-cancel').addEventListener('click',()=>{editor.hidden=true});editor.addEventListener('submit',async event=>{event.preventDefault();const submit=editor.querySelector('[type="submit"]');submit.disabled=true;try{const updated={...property,'Título':editor.title.value,'Preço (texto do site)':editor.price.value,'Endereço / localização exibida':editor.address.value};const response=await fetch(ADMIN_API_URL,{method:'POST',credentials:'include',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'update',property:updated})});const result=await response.json();if(!result.ok)throw new Error(result.error||'Não foi possível salvar.');title.textContent=updated['Título'];meta.textContent=`${updated.ID} · ${updated['Preço (texto do site)']} · ${updated['Endereço / localização exibida']}`;editor.hidden=true}catch(error){alert(error.message)}finally{submit.disabled=false}});item.append(title,meta,edit,editor);list.append(item)});document.querySelector('.admin-shell').append(panel);document.querySelector('.admin-access')?.classList.add('is-connected')};form.addEventListener('submit',async event=>{event.preventDefault();if(!form.checkValidity()){form.reportValidity();return}showMessage('Conectando à sua conta Google…');try{const response=await fetch(`${ADMIN_API_URL}?action=list`,{credentials:'include'});const result=await response.json();if(!result.ok)throw new Error(result.error||'A conta Google não foi autorizada.');if(form.querySelector('[name="remember"]').checked)localStorage.setItem('adminRememberedSession','true');else localStorage.removeItem('adminRememberedSession');render(result.properties||[])}catch(error){showMessage(`Não foi possível conectar: ${error.message||'resposta inválida do Apps Script.'}`)}})}
function initQuickEditor(){const panel=document.querySelector('.admin-dashboard');if(!panel||panel.dataset.quickReady)return;panel.dataset.quickReady='true';const form=document.createElement('form');form.className='admin-quick-editor';form.innerHTML='<div class="quick-heading"><div class="eyebrow">Editor de imóvel</div><h2>Edite o imóvel selecionado</h2><p>Altere os dados, gerencie as imagens e salve tudo em um único lugar.</p></div><label>Imóvel<select name="property" required><option value="">Carregando imóveis…</option></select></label><div class="quick-grid"><label class="quick-title-field">Título<textarea name="title" rows="3" required></textarea></label><label>Preço<input name="price" required></label></div><label>Descrição<textarea name="description" rows="6" placeholder="Descreva o imóvel, diferenciais e localização"></textarea></label><label>Status<select name="status"><option>Ativo</option><option>Vendido</option><option>Alugado</option><option>Desativado</option></select></label><label class="photo-picker">Fotos do celular<input name="photos" type="file" accept="image/*" multiple/><small>Você pode selecionar várias fotos de uma vez.</small></label><div class="quick-actions"><button type="submit">Salvar atualização <span>→</span></button><button type="button" class="quick-delete">Excluir imóvel</button></div><p class="quick-message" hidden></p>';panel.prepend(form);const select=form.property;const title=form.title;const price=form.price;const description=form.description;const status=form.status;const message=form.querySelector('.quick-message');let properties=[];const show=text=>{message.textContent=text;message.hidden=false};const load=async()=>{const response=await fetch(`${ADMIN_API_URL}?action=list`,{credentials:'include'});const result=await response.json();if(!result.ok)throw new Error(result.error||'Falha ao carregar imóveis.');properties=result.properties||[];select.replaceChildren(...properties.map(property=>{const option=new Option(`${property.ID} · ${property['Título']}`,property.ID);return option}));fill()};const fill=()=>{const property=properties.find(item=>item.ID===select.value)||properties[0];if(!property)return;select.value=property.ID;title.value=property['Título']||'';price.value=property['Preço (texto do site)']||'';description.value=property['Características e resumo da descrição']||'';status.value=property.Status||'Ativo'};select.addEventListener('change',fill);form.addEventListener('submit',async event=>{event.preventDefault();const property=properties.find(item=>item.ID===select.value);if(!property)return;const submit=form.querySelector('[type="submit"]');submit.disabled=true;try{const updated={...property,'Título':title.value,'Preço (texto do site)':price.value,'Características e resumo da descrição':description.value,Status:status.value};let response=await fetch(ADMIN_API_URL,{method:'POST',credentials:'include',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'update',property:updated})});let result=await response.json();if(!result.ok)throw new Error(result.error||'Não foi possível salvar.');const files=[...form.photos.files];for(let i=0;i<files.length;i++){const file=files[i];const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});response=await fetch(ADMIN_API_URL,{method:'POST',credentials:'include',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'uploadPhoto',propertyId:property.ID,title:title.value,order:i+1,fileName:file.name,mimeType:file.type,base64})});result=await response.json();if(!result.ok)throw new Error(result.error||'Falha ao enviar foto.')}show(files.length?`Atualizado e ${files.length} foto(s) enviada(s).`:'Imóvel atualizado com sucesso.');form.photos.value='';}catch(error){show(error.message)}finally{submit.disabled=false}});form.querySelector('.quick-delete').addEventListener('click',async()=>{const property=properties.find(item=>item.ID===select.value);if(!property||!await showAdminConfirm_(`Excluir ${property['Título']}? Esta ação não pode ser desfeita.`))return;try{const response=await fetch(ADMIN_API_URL,{method:'POST',credentials:'include',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'delete',id:property.ID})});const result=await response.json();if(!result.ok)throw new Error(result.error||'Não foi possível excluir.');show('Imóvel excluído.');properties=properties.filter(item=>item.ID!==property.ID);select.querySelector(`option[value="${property.ID}"]`)?.remove();fill()}catch(error){show(error.message)}});load().catch(error=>show('Não foi possível carregar o editor: '+error.message))}
new MutationObserver(()=>{initAdvancedFilters();initFilterUI();initSearchSuggestions();initHeaderMenu();initAdminPage();initQuickEditor()}).observe(document.querySelector('#app'),{childList:true,subtree:true});
const appPath=(pathname)=>{const query=new URLSearchParams(location.search);if(query.get('admin')==='1'||query.get('adminAuth')==='1'||query.has('adminToken'))return '/admin';if(basePath&&(pathname===basePath||pathname.startsWith(`${basePath}/`)))return pathname.slice(basePath.length)||'/';return pathname};
function App(){disposePageEffects();let path=appPath(location.pathname).replace(/\/$/,'')||'/';let p=properties.find(x=>x.url===path);let page=p?()=>Detail({p}):path==='/imoveis'?Imoveis:path==='/sobre'?Sobre:path==='/contato'?Contato:path==='/admin'||path==='/login'?Admin:path==='/privacidade'?Privacidade:Home;document.querySelector('#app').innerHTML=page()+Footer();document.querySelectorAll('a[href^="/"]').forEach(a=>{a.href=route(a.getAttribute('href'))});document.documentElement.classList.remove('page-motion');requestAnimationFrame(()=>document.documentElement.classList.add('page-motion'));initContactForm();document.querySelector('.filter-submit')?.addEventListener('click',()=>{const value=document.querySelector('.property-filter').value;const items=value==='all'?properties:properties.filter(x=>`${x.title} ${x.raw}`.toLowerCase().includes(value));const grid=document.querySelector('.listing .property-grid');if(grid)grid.outerHTML=PropertyGrid({items})});document.querySelectorAll('[data-gallery-src]').forEach(button=>button.addEventListener('click',()=>{const gallery=button.closest('.gallery-column');const image=gallery?.querySelector('.gallery-current');if(!image)return;image.src=button.dataset.gallerySrc;gallery.querySelectorAll('[data-gallery-src]').forEach(item=>item.classList.toggle('active',item===button||item.dataset.gallerySrc===button.dataset.gallerySrc))}));const updateHeader=()=>document.querySelectorAll('.header').forEach(h=>h.classList.toggle('scrolled',window.scrollY>18));updateHeader();window.addEventListener('scroll',updateHeader,{passive:true});registerPageCleanup(()=>window.removeEventListener('scroll',updateHeader))}
function navigate(path){const change=()=>{history.pushState({},'',route(path));App();cleanGalleryControls();addGalleryArrows();initTrackGalleries();initAdvancedFilters();initTitleAnimations();initFooterDeveloper();initFooterParallax();initFaqAccordions();initHeroLiquid();window.scrollTo(0,0)};if(document.startViewTransition)document.startViewTransition(change);else change()}
window.addEventListener('popstate',()=>{App();cleanGalleryControls();addGalleryArrows();initTrackGalleries();initAdvancedFilters();initTitleAnimations();initFooterDeveloper();initFooterParallax();initFaqAccordions();initContactSplit();initHeroLiquid()});document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&a.origin===location.origin&&a.dataset.external!=='true'){e.preventDefault();navigate(appPath(new URL(a.href).pathname))}});App();cleanGalleryControls();addGalleryArrows();initTrackGalleries();initAdvancedFilters();initTitleAnimations();initFooterDeveloper();initFooterParallax();initFaqAccordions();initContactSplit();initWhatsAppWidget();initGalleryZoom();initHeroLiquid();
function initHeroLiquid(){const hero=document.querySelector('.hero');if(!hero||hero.dataset.liquidReady)return;hero.dataset.liquidReady='true';if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const move=event=>{const rect=hero.getBoundingClientRect();const x=((event.clientX-rect.left)/rect.width-.5)*2;const y=((event.clientY-rect.top)/rect.height-.5)*2;hero.style.setProperty('--hero-x',x.toFixed(3));hero.style.setProperty('--hero-y',y.toFixed(3))};hero.addEventListener('pointermove',move);hero.addEventListener('pointerleave',()=>{hero.style.setProperty('--hero-x','0');hero.style.setProperty('--hero-y','0')})}
function initContactForm(){const form=document.querySelector('.contact-wrap form');if(!form||form.dataset.ready)return;form.dataset.ready='true';const review=form.querySelector('.contact-review');const summary=form.querySelector('.review-summary');const submit=form.querySelector('.submit');const error=document.createElement('p');error.className='form-error';error.hidden=true;form.insertBefore(error,review);const started=performance.now();const data=()=>Object.fromEntries(new FormData(form).entries());const renderSummary=values=>{summary.replaceChildren();[['Objetivo',values.objetivo],['Nome',values.nome],['Telefone',values.telefone],['Email',values.email],['Mensagem',values.mensagem]].forEach(([label,value])=>{const item=document.createElement('div');const title=document.createElement('strong');title.textContent=label;const text=document.createElement('span');text.textContent=value;item.append(title,text);summary.append(item)})};form.addEventListener('submit',event=>{event.preventDefault();error.hidden=true;if(form.website.value.trim()){error.textContent='Não foi possível enviar esta mensagem.';error.hidden=false;return}if(performance.now()-started<900){error.textContent='Aguarde alguns instantes e revise os campos antes de enviar.';error.hidden=false;return}if(!form.checkValidity()){form.reportValidity();return}renderSummary(data());review.hidden=false;submit.hidden=true});form.querySelector('.review-edit').addEventListener('click',()=>{review.hidden=true;submit.hidden=false});form.querySelector('.review-confirm').addEventListener('click',()=>{review.hidden=true;form.querySelector('.success').hidden=false})}
function initAdminControls_(){const panel=document.querySelector('.admin-dashboard');if(!panel||panel.dataset.controlsReady)return;panel.dataset.controlsReady='true';const head=panel.querySelector('.admin-dashboard-head');const list=panel.querySelector('.admin-property-list');const toolbar=document.createElement('div');toolbar.className='admin-toolbar';toolbar.innerHTML='<input type="search" placeholder="Filtrar imóveis" aria-label="Filtrar imóveis"><select aria-label="Filtrar status"><option value="all">Todos os status</option><option>Ativo</option><option>Vendido</option><option>Alugado</option><option>Desativado</option></select><button type="button" class="admin-new-property">+ Adicionar novo imóvel</button>';head.append(toolbar);const create=document.createElement('form');create.className='admin-create-form';create.hidden=true;create.innerHTML='<div class="quick-heading"><div class="eyebrow">Novo cadastro</div><h2>Adicionar imóvel</h2><p>Preencha os dados principais e envie as fotos do imóvel.</p></div><div class="admin-create-grid"><label>ID<input value="Automático" readonly></label><label>Operação<select name="Operação"><option>Venda</option><option>Locação</option></select></label><label class="create-title-field">Título<textarea name="Título" rows="3" required></textarea></label><label>Preço<input name="Preço (texto do site)" required></label><label>Endereço<input name="Endereço / localização exibida"></label><label>Área<input name="Área"></label><label>Quartos<input name="Quartos"></label><label>Banheiros<input name="Banheiros"></label><label>Andares<input name="Andares (campo do site)"></label><label>Condomínio<input name="Condomínio"></label><label>IPTU<input name="IPTU"></label><label>Status<select name="Status"><option>Ativo</option><option>Vendido</option><option>Alugado</option><option>Desativado</option></select></label></div><label>Descrição<textarea name="Características e resumo da descrição" rows="6"></textarea></label><label class="photo-picker">Fotos<input name="photos" type="file" accept="image/*" multiple></label><div class="quick-actions"><button type="submit">Criar imóvel</button><button type="button" class="admin-cancel-create">Cancelar</button></div><p class="quick-message" hidden></p>';panel.insertBefore(create,list);const getRows=()=>fetch(`${ADMIN_API_URL}?action=list`).then(response=>response.json()).then(result=>result.properties||[]);const post=payload=>fetch(ADMIN_API_URL,{method:'POST',credentials:'include',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(payload)});const upload=async(propertyId,title,files)=>{for(let i=0;i<files.length;i++){const file=files[i];const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});await post({action:'uploadPhoto',propertyId,title,order:i+1,fileName:file.name,mimeType:file.type,base64})}};const refresh=()=>getRows().then(rows=>{list.querySelectorAll('.admin-property').forEach((card,index)=>{const property=rows[index];if(!property)return;const actions=document.createElement('div');actions.className='admin-card-actions';actions.innerHTML='<select aria-label="Status do imóvel"><option>Ativo</option><option>Vendido</option><option>Alugado</option><option>Desativado</option></select><button type="button" class="admin-clone">Clonar</button><button type="button" class="admin-remove">Excluir</button>';const select=actions.querySelector('select');select.value=property.Status||'Ativo';select.addEventListener('change',()=>post({action:'status',id:property.ID,status:select.value}).then(()=>{select.blur()}));actions.querySelector('.admin-clone').addEventListener('click',()=>{const copy={...property,ID:`${property.ID}-C`,Título:`${property['Título']} (cópia)`,Status:'Ativo'};post({action:'create',property:copy}).then(()=>location.reload())});actions.querySelector('.admin-remove').addEventListener('click',async()=>{if(await showAdminConfirm_(`Excluir ${property['Título']}?`))post({action:'delete',id:property.ID}).then(()=>location.reload())});card.append(actions)})});toolbar.querySelector('input').addEventListener('input',event=>{const query=event.target.value.toLocaleLowerCase('pt-BR');list.querySelectorAll('.admin-property').forEach(card=>{card.hidden=!card.textContent.toLocaleLowerCase('pt-BR').includes(query)})});toolbar.querySelector('select').addEventListener('change',event=>{const value=event.target.value;list.querySelectorAll('.admin-property').forEach(card=>{const select=card.querySelector('.admin-card-actions select');card.hidden=value!=='all'&&select?.value!==value})});toolbar.querySelector('.admin-new-property').addEventListener('click',()=>{create.hidden=!create.hidden;create.scrollIntoView({behavior:'smooth',block:'center'})});create.querySelector('.admin-cancel-create').addEventListener('click',()=>{create.hidden=true});create.addEventListener('submit',async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(create).entries());const files=[...create.photos.files];delete data.photos;const property={...data,Status:data.Status,'Status CMS':data.Status==='Ativo'?'Publicado':data.Status,URL:'',Fotos:'',Destaque:'FALSE',Slug:'', 'Atualizado em':''};const button=create.querySelector('[type="submit"]');let progress=create.querySelector('.admin-progress');if(!progress){progress=document.createElement('div');progress.className='admin-progress';progress.innerHTML='<div class="admin-progress-track"><span></span></div><small></small>';create.querySelector('.quick-actions').before(progress)}const progressBar=progress.querySelector('span');const progressText=progress.querySelector('small');const setProgress=(value,text)=>{progress.hidden=false;progressBar.style.width=`${value}%`;progressText.textContent=text};button.disabled=true;setProgress(8,'Preparando cadastro…');try{const createResponse=await fetch(`${ADMIN_API_URL}?action=create&payload=${encodeURIComponent(JSON.stringify(property))}`);const createResult=await createResponse.json();if(!createResult.ok)throw new Error(createResult.error||'Não foi possível criar o imóvel.');setProgress(35,files.length?'Enviando imagens…':'Finalizando cadastro…');await upload(property.ID,property['Título'],files);setProgress(100,'Cadastro concluído.');create.querySelector('.quick-message').textContent='Imóvel criado com sucesso.';create.querySelector('.quick-message').hidden=false;setTimeout(()=>location.reload(),700)}catch(error){create.querySelector('.quick-message').textContent=error.message;create.querySelector('.quick-message').hidden=false}finally{button.disabled=false}});refresh()}
function addCityFields_(){const create=document.querySelector('.admin-create-form .admin-create-grid');if(create&&!create.querySelector('[name="Cidade"]')){const label=document.createElement('label');label.textContent='Cidade';const input=document.createElement('input');input.name='Cidade';input.required=true;input.placeholder='Preenchida pelo CEP ou digite';label.append(input);const address=create.querySelector('[name="Endereço / localização exibida"]')?.closest('label');address?.after(label)}const full=document.querySelector('.admin-full-grid');if(full&&!full.querySelector('[name="city"]')){const label=document.createElement('label');label.textContent='Cidade';const input=document.createElement('input');input.name='city';input.placeholder='Preenchida pelo CEP ou digite';label.append(input);full.prepend(label);const quick=document.querySelector('.admin-quick-editor');if(quick&&!quick.dataset.cityFetchReady){quick.dataset.cityFetchReady='true';const previousFetch=window.fetch;window.fetch=(url,options={})=>{if(String(url).startsWith(ADMIN_API_URL)&&(options.method||'GET').toUpperCase()==='POST'){try{const payload=JSON.parse(options.body||'{}');if(payload.action==='update'&&payload.property){payload.property.Cidade=input.value;options={...options,body:JSON.stringify(payload)}}}catch(error){}}return previousFetch(url,options)}}}}
function initAddressLookup_(){const form=document.querySelector('.admin-create-form');if(!form||form.dataset.addressLookupReady)return;const grid=form.querySelector('.admin-create-grid');const address=form.querySelector('[name="Endereço / localização exibida"]');const city=form.querySelector('[name="Cidade"]');if(!grid||!address||!city)return;form.dataset.addressLookupReady='true';const label=document.createElement('label');label.className='cep-lookup-field';label.textContent='CEP';const input=document.createElement('input');input.name='CEP';input.inputMode='numeric';input.placeholder='00000-000';input.maxLength=9;const button=document.createElement('button');button.type='button';button.className='cep-lookup-button';button.textContent='Buscar endereço';const message=document.createElement('small');message.className='cep-lookup-message';label.append(input,button,message);const addressLabel=address.closest('label');addressLabel?.before(label);const setCity=value=>{city.value=String(value||'').trim()};const lookup=async()=>{const cep=input.value.replace(/\D/g,'');if(cep.length!==8){message.textContent='Digite um CEP válido com 8 números.';return}button.disabled=true;message.textContent='Buscando endereço…';try{const response=await fetch(`https://brasilapi.com.br/api/cep/v2/${cep}`);if(!response.ok)throw new Error('CEP não encontrado.');const result=await response.json();address.value=[result.street,result.neighborhood].filter(Boolean).join(', ');setCity(result.city);message.textContent=`${result.city || ''} — ${result.state || ''}`.trim()}catch(error){message.textContent=error.message}finally{button.disabled=false}};button.addEventListener('click',lookup);input.addEventListener('input',()=>{input.value=input.value.replace(/\D/g,'').replace(/(\d{5})(\d)/,'$1-$2')});input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();lookup()}});address.addEventListener('blur',async()=>{if(city.value||address.value.trim().length<6)return;try{const response=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=br&q=${encodeURIComponent(address.value)}`);const result=await response.json();const found=result[0]?.address?.city||result[0]?.address?.town||result[0]?.address?.municipality;if(found)setCity(found)}catch(error){}})}
function initPropertyFieldFormatting_(){document.querySelectorAll('.admin-create-form,.admin-quick-editor').forEach(form=>{if(form.dataset.fieldFormattingReady)return;form.dataset.fieldFormattingReady='true';const area=form.querySelector('[name="Área"], [name="area"]');const price=form.querySelector('[name="Preço (texto do site)"], [name="price"]');const condo=form.querySelector('[name="Condomínio"], [name="condo"]');const iptu=form.querySelector('[name="IPTU"], [name="iptu"]');const floor=form.querySelector('[name="Andares (campo do site)"], [name="floors"]');const labelFor=field=>field?.closest('label');const setLabel=(field,text)=>{const label=labelFor(field);if(label?.firstChild?.nodeType===Node.TEXT_NODE)label.firstChild.textContent=text};const numberValue=value=>String(value||'').replace(/[^0-9,.-]/g,'').replace(',','.');const formatArea=()=>{const value=numberValue(area?.value);if(area&&value)area.value=`${value.replace(/\.0+$/,'')}m²`};const formatMoney=field=>{if(!field)return;const raw=String(field.value||'').trim();if(!raw)return;const normalized=raw.includes(',')?raw.replace(/\./g,'').replace(',','.'):raw.replace(/[^0-9.-]/g,'');const value=Number(normalized);if(Number.isNaN(value))return;field.value=value.toLocaleString('pt-BR',{style:'currency',currency:'BRL'})};const formatFloor=()=>{if(!floor)return;const match=String(floor.value).match(/\d+/);if(match)floor.value=`${Number(match[0])}º andar`};area?.addEventListener('blur',formatArea);[price,condo,iptu].forEach(field=>field?.addEventListener('blur',()=>formatMoney(field)));floor?.addEventListener('blur',formatFloor);setLabel(floor,'Andar')})}
