function consolidateAdminEditor_(){const panel=document.querySelector('.admin-dashboard');const quick=panel?.querySelector('.admin-quick-editor');if(!panel||!quick||quick.dataset.completeReady)return;quick.dataset.completeReady='true';const head=panel.querySelector('.admin-dashboard-head');const list=panel.querySelector('.admin-property-list');const toolbar=head?.querySelector('.admin-toolbar');const logout=head?.querySelector('.admin-logout');if(toolbar)quick.querySelector('.quick-heading').append(toolbar);if(logout)quick.querySelector('.quick-heading').append(logout);if(head)head.hidden=true;if(list)list.hidden=true;const create=panel.querySelector('.admin-create-form');if(create)quick.after(create);const full=document.createElement('div');full.className='admin-full-grid';full.innerHTML='<label>Operação<select name="operation"><option>Venda</option><option>Locação</option></select></label><label>Endereço<input name="address"></label><label>Área<input name="area"></label><label>Quartos<input name="rooms"></label><label>Banheiros<input name="baths"></label><label>Andares<input name="floors"></label><label>Condomínio<input name="condo"></label><label>IPTU<input name="iptu"></label>';quick.querySelector('.quick-grid').after(full);const select=quick.property;const fields={operation:full.querySelector('[name="operation"]'),address:full.querySelector('[name="address"]'),area:full.querySelector('[name="area"]'),rooms:full.querySelector('[name="rooms"]'),baths:full.querySelector('[name="baths"]'),floors:full.querySelector('[name="floors"]'),condo:full.querySelector('[name="condo"]'),iptu:full.querySelector('[name="iptu"]')};const imageList=document.createElement('div');imageList.className='admin-image-list';quick.querySelector('.photo-picker').after(imageList);let rows=[];const filterPropertyOptions=()=>{const query=toolbar?.querySelector('input')?.value.toLocaleLowerCase('pt-BR')||'';const statusFilter=toolbar?.querySelector('select')?.value||'all';const current=select.value;const filtered=rows.filter(property=>(!query||`${property.ID} ${property['Título']}`.toLocaleLowerCase('pt-BR').includes(query))&&(statusFilter==='all'||(property.Status||'Ativo')===statusFilter));select.replaceChildren(...filtered.map(property=>new Option(`${property.ID} · ${property['Título']}`,property.ID)));if(filtered.some(property=>property.ID===current))select.value=current;fill();renderImages()};toolbar?.querySelector('input')?.addEventListener('input',filterPropertyOptions);toolbar?.querySelector('select')?.addEventListener('change',filterPropertyOptions);const renderImages=()=>{const property=rows.find(item=>item.ID===select.value)||rows[0];imageList.replaceChildren();if(!property||!property.Images?.length){imageList.innerHTML='<small class="admin-no-images">Nenhuma imagem enviada ainda.</small>';return}let draggedId='';const persistOrder=()=>fetch(ADMIN_API_URL,{method:'POST',credentials:'include',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'reorderPhotos',propertyId:property.ID,photoIds:property.Images.map(image=>image.id||image.url||image.localSrc)})});property.Images.forEach((image,index)=>{const item=document.createElement('div');item.className='admin-image-item';item.draggable=true;item.dataset.photoId=image.id||image.url||image.localSrc;item.innerHTML=`<span class="admin-image-order">${index===0?'Destaque':index+1}</span><img src="${image.url||image.localSrc}" alt="Imagem ${index+1}"><div class="admin-image-actions"><button type="button" class="move-up" aria-label="Mover imagem para cima">↑</button><button type="button" class="move-down" aria-label="Mover imagem para baixo">↓</button><button type="button" class="delete-image" aria-label="Excluir imagem ${index+1}">Excluir</button></div>`;item.addEventListener('dragstart',()=>{draggedId=item.dataset.photoId;item.classList.add('is-dragging')});item.addEventListener('dragend',()=>item.classList.remove('is-dragging'));item.addEventListener('dragover',event=>event.preventDefault());item.addEventListener('drop',async event=>{event.preventDefault();if(!draggedId||draggedId===item.dataset.photoId)return;const from=property.Images.findIndex(photo=>(photo.id||photo.url||photo.localSrc)===draggedId);const to=property.Images.findIndex(photo=>(photo.id||photo.url||photo.localSrc)===item.dataset.photoId);const [moved]=property.Images.splice(from,1);property.Images.splice(to,0,moved);renderImages();await persistOrder()});item.querySelector('.move-up').addEventListener('click',async()=>{if(index===0)return;const moved=property.Images.splice(index,1)[0];property.Images.splice(index-1,0,moved);renderImages();await persistOrder()});item.querySelector('.move-down').addEventListener('click',async()=>{if(index===property.Images.length-1)return;const moved=property.Images.splice(index,1)[0];property.Images.splice(index+1,0,moved);renderImages();await persistOrder()});item.querySelector('.delete-image').addEventListener('click',async()=>{if(!await showAdminConfirm_('Excluir esta imagem?'))return;await fetch(ADMIN_API_URL,{method:'POST',credentials:'include',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'deletePhoto',propertyId:property.ID,photoId:image.id,photoUrl:image.url||image.localSrc})});await loadRows()});imageList.append(item)})};const loadRows=()=>fetch(`${ADMIN_API_URL}?action=list`).then(response=>response.json()).then(result=>{rows=result.properties||[];fill();renderImages();return rows});const fill=()=>{const p=rows.find(item=>item.ID===select.value)||rows[0];if(!p)return;fields.operation.value=p['Operação']||'Venda';fields.address.value=p['Endereço / localização exibida']||'';fields.area.value=p.Área||'';fields.rooms.value=p.Quartos||'';fields.baths.value=p.Banheiros||'';fields.floors.value=p['Andares (campo do site)']||'';fields.condo.value=p.Condomínio||'';fields.iptu.value=p.IPTU||''};select.addEventListener('change',()=>{fill();renderImages()});setTimeout(fill,300);const clone=document.createElement('button');clone.type='button';clone.className='quick-clone';clone.textContent='Clonar imóvel';quick.querySelector('.quick-actions').append(clone);clone.addEventListener('click',()=>{const p=rows.find(item=>item.ID===select.value);if(!p)return;const copy={...p,ID:`${p.ID}-C`,Título:`${p['Título']} (cópia)`,Status:'Ativo'};fetch(ADMIN_API_URL,{method:'POST',credentials:'include',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'create',property:copy})}).then(()=>location.reload())});quick.addEventListener('submit',async event=>{event.preventDefault();event.stopImmediatePropagation();const p=rows.find(item=>item.ID===select.value);if(!p)return;const files=[...quick.photos.files];const updated={...p,'Título':quick.title.value,'Preço (texto do site)':quick.price.value,'Operação':fields.operation.value,'Endereço / localização exibida':fields.address.value,'Área':fields.area.value,'Quartos':fields.rooms.value,'Banheiros':fields.baths.value,'Andares (campo do site)':fields.floors.value,'Condomínio':fields.condo.value,'IPTU':fields.iptu.value,'Características e resumo da descrição':quick.description.value,Status:quick.status.value};const button=quick.querySelector('[type="submit"]');let progress=quick.querySelector('.admin-progress');if(!progress){progress=document.createElement('div');progress.className='admin-progress';progress.innerHTML='<div class="admin-progress-track"><span></span></div><small></small>';quick.querySelector('.quick-actions').before(progress)}const progressBar=progress.querySelector('span');const progressText=progress.querySelector('small');const setProgress=(value,text)=>{progress.hidden=false;progressBar.style.width=`${value}%`;progressText.textContent=text};button.disabled=true;setProgress(8,'Preparando atualização…');try{await fetch(ADMIN_API_URL,{method:'POST',credentials:'include',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'update',property:updated})});setProgress(35,files.length?'Enviando imagens…':'Finalizando atualização…');for(let i=0;i<files.length;i++){const file=files[i];const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});await fetch(ADMIN_API_URL,{method:'POST',credentials:'include',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'uploadPhoto',propertyId:p.ID,title:updated['Título'],order:i+1,fileName:file.name,mimeType:file.type,base64})});setProgress(35+Math.round(((i+1)/files.length)*55),`Enviando imagem ${i+1} de ${files.length}…`)}setProgress(100,'Atualização concluída.');quick.querySelector('.quick-message').textContent='Imóvel atualizado com sucesso.';quick.querySelector('.quick-message').hidden=false;quick.photos.value='';rows=await loadRows()}catch(error){quick.querySelector('.quick-message').textContent=error.message;quick.querySelector('.quick-message').hidden=false}finally{button.disabled=false}},true);loadRows()}
