function initAdminFilterDropdown_(){const toolbar=document.querySelector('.admin-quick-editor .admin-toolbar');const input=toolbar?.querySelector('input[type="search"]');const select=document.querySelector('.admin-quick-editor select[name="property"]');if(!toolbar||!input||!select||input.dataset.dropdownReady)return;input.dataset.dropdownReady='true';const field=document.createElement('div');field.className='admin-filter-field';const dropdown=document.createElement('div');dropdown.className='admin-filter-dropdown';dropdown.hidden=true;input.parentNode.insertBefore(field,input);field.append(input,dropdown);const hide=()=>{dropdown.hidden=true};const render=()=>{const query=input.value.trim().toLocaleLowerCase('pt-BR');if(!query){hide();return}const matches=[...select.options].filter(option=>option.textContent.toLocaleLowerCase('pt-BR').includes(query)).slice(0,8);dropdown.replaceChildren(...matches.map(option=>{const button=document.createElement('button');button.type='button';button.className='admin-filter-option';button.textContent=option.textContent;button.addEventListener('click',()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));input.value='';input.dispatchEvent(new Event('input',{bubbles:true}));hide()});return button}));dropdown.hidden=!matches.length};input.addEventListener('input',render);input.addEventListener('focus',()=>{if(input.value.trim())render()});document.addEventListener('click',event=>{if(!field.contains(event.target))hide()})}
new MutationObserver(()=>initAdminFilterDropdown_()).observe(document.querySelector('#app'),{childList:true,subtree:true});
